const rawInput = $input.first().json;
const body = rawInput.body || rawInput;

if (!body || !body.data) {
  return [];
}

const event = String(body.event || "").toLowerCase();
if (event && event !== "messages.upsert" && event !== "messages_upsert") {
  return [];
}

const data = Array.isArray(body.data) ? body.data[0] : body.data;
const key = data.key || {};
const message = data.message || {};

if (key.fromMe === true) {
  return [];
}

const actualMessage = message.ephemeralMessage?.message || message.viewOnceMessage?.message || message;

let messageType = "text";
let userText = "";
let mediaUrl = null;

if (actualMessage.conversation) {
  userText = actualMessage.conversation;
  messageType = "text";
} else if (actualMessage.extendedTextMessage?.text) {
  userText = actualMessage.extendedTextMessage.text;
  messageType = "text";
} else if (actualMessage.audioMessage) {
  messageType = "audio";
  userText = "[MENSAJE_DE_VOZ_RECIBIDO]";
  mediaUrl = actualMessage.audioMessage.url || null;
} else if (actualMessage.imageMessage) {
  messageType = "image";
  userText = actualMessage.imageMessage.caption || "[IMAGEN_SIN_TEXTO]";
  mediaUrl = actualMessage.imageMessage.url || null;
} else if (actualMessage.stickerMessage) {
  messageType = "sticker";
  userText = "[STICKER_RECIBIDO]";
} else if (actualMessage.videoMessage) {
  messageType = "video";
  userText = actualMessage.videoMessage.caption || "[VIDEO_RECIBIDO]";
} else if (actualMessage.documentMessage) {
  messageType = "document";
  userText = actualMessage.documentMessage.caption || "[DOCUMENTO_RECIBIDO]";
}

function formatPhone(p) {
  if (!p) return "";
  if (String(p).includes("@g.us")) return p;
  const c = String(p).replace(/\D/g, "");
  if (c.length === 10) return "57" + c;
  if (c.length === 12 && c.startsWith("57")) return c;
  return c;
}

const remoteJid = key.remoteJid || "";
let rawPhone = remoteJid;
if (rawPhone.includes("@s.whatsapp.net")) {
  rawPhone = rawPhone.replace("@s.whatsapp.net", "");
} else if (rawPhone.includes("@lid") && key.participant && key.participant.includes("@s.whatsapp.net")) {
  rawPhone = key.participant.replace("@s.whatsapp.net", "");
}
const userPhone = remoteJid.includes("@g.us") ? remoteJid : formatPhone(rawPhone);
const instanceName = body.instance || body.instanceName || rawInput.instance || "canchas_4dd6d2dce9f9";

const trimmedText = userText.trim();
const match = trimmedText.match(/(aprobar|aprobas|aprobás|aprovar|cancelar|confirmar|rechazar)\s*([a-zA-Z0-9_-]{4,12})/i);
let isOwnerCommand = false;
let commandAction = "";
let commandCode = "";

if (match) {
  isOwnerCommand = true;
  const verb = match[1].toLowerCase();
  commandAction = (verb.includes("aprob") || verb === "confirmar") ? "confirmed" : "cancelled";
  commandCode = match[2];
}

return [{
  json: {
    sessionId: userPhone || remoteJid,
    instance: instanceName,
    remoteJid: remoteJid,
    userPhone: userPhone || remoteJid,
    messageType: messageType,
    messageText: trimmedText,
    mediaUrl: mediaUrl,
    isOwnerCommand: isOwnerCommand,
    commandAction: commandAction,
    commandCode: commandCode
  }
}];

const msgType = $('Normalize Incoming Message').item.json.messageType;
let companyName = "nuestro complejo deportivo";
try {
  companyName = $('Get Company Details').item.json.name || companyName;
} catch(e) {}

let reply = "";

if (msgType === "audio") {
  reply = `¡Hola! 🎙️ He recibido tu nota de voz. Soy el asistente virtual de ${companyName} y por este canal no puedo escuchar audios directamente.

Por favor, escríbeme por mensaje de texto qué día y a qué hora te gustaría jugar, y con mucho gusto te confirmo la disponibilidad de inmediato ⚽`;
} else if (msgType === "image") {
  reply = `¡Hola! 📸 He recibido tu imagen. Soy el asistente virtual de ${companyName}.

• Si se trata de un comprobante de anticipo o pago, nuestro equipo administrativo lo revisará en breve para verificarlo.
• Si deseas consultar horarios o reservar cancha, por favor escríbeme por texto qué día y hora buscas jugar para ayudarte de una vez ⚽`;
} else if (msgType === "sticker") {
  reply = `¡Hola crack! ⚽ Soy el asistente virtual de ${companyName}.

Por favor, escríbeme por mensaje de texto qué día y a qué hora te gustaría jugar para confirmarte la disponibilidad de inmediato 🔥`;
} else {
  reply = `¡Hola! 📄 He recibido tu archivo multimedia. Soy el asistente virtual de ${companyName}.

Por favor, escríbeme por mensaje de texto qué día y a qué hora buscas jugar para confirmarte la cancha y horarios disponibles de inmediato ⚽`;
}

return [{
  json: {
    replyText: reply
  }
}];

